17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
37	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
38	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /**
65	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
66	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
67	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
68	     */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        List<String> missingFields = new ArrayList<>();
119	        if (isBlank(ownerFieldsDto.getFirstName())) {
120	            missingFields.add("firstName");
121	        }
122	        if (isBlank(ownerFieldsDto.getLastName())) {
123	            missingFields.add("lastName");
124	        }
125	        if (isBlank(ownerFieldsDto.getAddress())) {
126	            missingFields.add("address");
127	        }
128	        if (isBlank(ownerFieldsDto.getCity())) {
129	            missingFields.add("city");
130	        }
131	        if (isBlank(ownerFieldsDto.getTelephone())) {
132	            missingFields.add("telephone");
133	        }
134	        if (!missingFields.isEmpty()) {
135	            throw new MissingOwnerFieldsException(missingFields);
136	        }
137	        String telephone = ownerFieldsDto.getTelephone().replaceAll("\\D", "");
138	        if (telephone.length() != 10) {
139	            throw new InvalidTelephoneException(
140	                "telephone must contain exactly 10 digits after removing non-digit characters");
141	        }
142	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
143	            .anyMatch(existing -> telephone.equals(normalizeTelephone(existing.getTelephone())));
144	        if (telephoneInUse) {
145	            throw new DuplicateTelephoneException(
146	                "an owner with the same normalized telephone already exists");
147	        }
148	        ownerFieldsDto.setTelephone(telephone);
149	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
150	        HttpHeaders headers = new HttpHeaders();
151	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
152	        if (owner.getRegistrationDate() == null) {
153	            owner.setRegistrationDate(LocalDate.now());
154	        }
155	        this.clinicService.saveOwner(owner);
156	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
157	        headers.setLocation(UriComponentsBuilder.newInstance()
158	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
159	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
165	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
166	        if (currentOwner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        currentOwner.setAddress(ownerFieldsDto.getAddress());
170	        currentOwner.setCity(ownerFieldsDto.getCity());
171	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
172	        currentOwner.setLastName(ownerFieldsDto.getLastName());
173	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
174	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
175	        this.clinicService.saveOwner(currentOwner);
176	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Transactional
181	    @Override
182	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
183	        Owner owner = this.clinicService.findOwnerById(ownerId);
184	        if (owner == null) {
185	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	        }
187	        this.clinicService.deleteOwner(owner);
188	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
194	        Owner owner = this.clinicService.findOwnerById(ownerId);
195	        if (owner == null) {
196	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	        }
198	        HttpHeaders headers = new HttpHeaders();
199	        Pet pet = petMapper.toPet(petFieldsDto);
200	        owner.setId(ownerId);
201	        pet.setOwner(owner);
202	        pet.getType().setName(null);
203	        this.clinicService.savePet(pet);
204	        PetDto petDto = petMapper.toPetDto(pet);
205	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
206	            .buildAndExpand(pet.getId()).toUri());
207	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
213	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
214	        if (currentOwner != null) {
215	            Pet currentPet = this.clinicService.findPetById(petId);
216	            if (currentPet != null) {
217	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
218	                currentPet.setName(petFieldsDto.getName());
219	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
220	                this.clinicService.savePet(currentPet);
221	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
222	            }
223	        }
224	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
225	    }
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Override
229	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
230	        HttpHeaders headers = new HttpHeaders();
231	        Visit visit = visitMapper.toVisit(visitFieldsDto);
232	        Pet pet = new Pet();
233	        pet.setId(petId);
234	        visit.setPet(pet);
235	        this.clinicService.saveVisit(visit);
236	        VisitDto visitDto = visitMapper.toVisitDto(visit);
237	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
238	            .buildAndExpand(visit.getId()).toUri());
239	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
240	    }
241	
242	
243	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
244	    @Override
245	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
246	        Owner owner = this.clinicService.findOwnerById(ownerId);
247	        if (owner != null) {
248	            Pet pet = owner.getPet(petId);
249	            if (pet != null) {
250	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
251	            }
252	        }
253	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
254	    }
255	
256	    private static boolean isBlank(String value) {
257	        return value == null || value.isBlank();
258	    }
259	
260	    private static String normalizeTelephone(String telephone) {
261	        return telephone == null ? null : telephone.replaceAll("\\D", "");
262	    }
263	
264	    /**
265	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
266	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
267	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
268	     * stored and returned in canonical form.
269	     */
270	    private static String normalizeEmail(String email) {
271	        if (isBlank(email)) {
272	            return null;
273	        }
274	        String trimmed = email.trim();
275	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
276	            throw new InvalidEmailException("email must be a syntactically valid address");
277	        }
278	        return trimmed.toLowerCase(Locale.ROOT);
279	    }
280	}
