215	     * offending {@code telephone} field.
216	     *
217	     * @param e The {@link DuplicateTelephoneException} to be handled
218	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
219	     */
220	    @ExceptionHandler(DuplicateTelephoneException.class)
221	    @ResponseBody
222	    public ResponseEntity<Map<String, Object>> handleDuplicateTelephoneException(DuplicateTelephoneException e) {
223	        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("errors", List.of("telephone")));
224	    }
